CREATE TYPE "TimeBalanceType" AS ENUM ('OVERTIME','RECOVERY','MANUAL_ADJUSTMENT','CORRECTION','OPENING_BALANCE'); CREATE TABLE "TimeBalanceTransaction"("id" UUID NOT NULL,"companyId" UUID NOT NULL,"userId" UUID NOT NULL,"workEntryId" UUID,"minutes" INTEGER NOT NULL,"type" "TimeBalanceType" NOT NULL,"reason" TEXT,"createdByUserId" UUID,"createdAt" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "TimeBalanceTransaction_pkey" PRIMARY KEY("id"),CONSTRAINT "TimeBalanceTransaction_workEntryId_type_key" UNIQUE("workEntryId","type")); CREATE INDEX "TimeBalanceTransaction_companyId_userId_createdAt_idx" ON "TimeBalanceTransaction"("companyId","userId","createdAt"); ALTER TABLE "TimeBalanceTransaction" ADD FOREIGN KEY("companyId") REFERENCES "Company"("id") ON DELETE CASCADE; ALTER TABLE "TimeBalanceTransaction" ADD FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE CASCADE; ALTER TABLE "TimeBalanceTransaction" ADD FOREIGN KEY("workEntryId") REFERENCES "WorkEntry"("id") ON DELETE SET NULL; ALTER TABLE "TimeBalanceTransaction" ENABLE ROW LEVEL SECURITY; ALTER TABLE "TimeBalanceTransaction" FORCE ROW LEVEL SECURITY; CREATE POLICY "balance_tenant" ON "TimeBalanceTransaction" FOR ALL USING("companyId"=NULLIF(current_setting('app.company_id',true),'')::uuid) WITH CHECK("companyId"=NULLIF(current_setting('app.company_id',true),'')::uuid);